const input = items[0].json;

const userSummary = `
Analyze this romantic relationship based on the user's answers:

- Emotional Safety: ${input.emotionalSafety}
- Conflict Resolution: ${input.conflictResolution}
- Shared Goals: ${input.sharedGoals}
- Trust Level: ${input.trustLevel}
- Respects Boundaries: ${input.respectBoundaries}
- Supports Growth: ${input.supportGrowth}
- Love Language Awareness: ${input.loveLanguageAwareness}
- Lifestyle Alignment: ${input.lifestyleAlignment}
- Jealousy or Control Issues: ${input.jealousyControl}
- Shared Fun: ${input.funFactor}
- Social Integration: ${input.socialIntegration}
- Reason for Love: ${input.loveReason}
- Desired Improvement: ${input.improveThing}
- You initiate contact: ${input.youInitiate}
- They initiate contact: ${input.theyInitiate}
- You sacrifice: ${input.youSacrifice}
- They sacrifice: ${input.theySacrifice}
- Love expression: ${input.loveExpression}

Please respond with:
1. A summary of compatibility
2. Who seems to be more emotionally invested
3. Advice or insights for strengthening the relationship
`.trim();

return [{ json: { prompt: userSummary } }];
